def solve():
    S = [1, 2, 3, 4, 5]
    P1 = [f - g for f in S for g in S]
    P1 = list(set(P1))

    def check(r):
        P2 = [3 * p * q * r for p in P1 for q in P1]
        A = [x**2 for x in P1]
        P3 = []
        for x in A:
            for y in A:
                for z in A:
                    for w in A:
                        P3.append(x + y - z - w)
        P3 = set(P3)
        for p in P2:
            if p not in P3:
                return False
        return True

    results = {}
    for r in [0, 1/3, 2/3, -1/3, -2/3, 1, -1]:
        results[r] = check(r)
    return results

